"""Shared graph DSL and small field helpers; no fixture-specific graph state."""
from ..graph import Graph, V


def choose(g, condition, yes, no, kind='FLOAT'):
    n = g.node('GeometryNodeSwitch', 'Choose')
    n.input_type = kind
    g.bind(condition, n.inputs['Switch'])
    g.bind(yes, n.inputs['True'])
    g.bind(no, n.inputs['False'])
    return V(g, n.outputs['Output'])


def bounded(g, value, lo=0., hi=1.):
    return g.math('MINIMUM', g.math('MAXIMUM', value, lo), hi)


def smooth(t):
    return t*t*t*(10+t*(-15+6*t))


def named(g, name, kind='FLOAT'):
    n = g.node('GeometryNodeInputNamedAttribute', name)
    n.data_type = kind
    n.inputs['Name'].default_value = name
    return V(g, n.outputs['Attribute'])


def remove(g, geometry, name):
    n = g.node('GeometryNodeRemoveAttribute', 'Remove '+name)
    g.bind(geometry, n.inputs['Geometry'])
    n.inputs['Name'].default_value = name
    return V(g, n.outputs['Geometry'])


def repeat(g, geometry, iterations, label):
    end = g.node('GeometryNodeRepeatOutput', label+' output')
    start = g.node('GeometryNodeRepeatInput', label+' input')
    start.pair_with_output(end)
    g.bind(geometry, start.inputs['Geometry'])
    g.bind(iterations, start.inputs['Iterations'])
    return start, end
